function mergeTwoLists(list1: ListNode | null, list2: ListNode | null): ListNode | null {
  // Фиктивная голова: не нужно отдельно решать, кто станет первым узлом
  const dummy = new ListNode(0);
  // tail — последний узел уже собранного результата
  let tail = dummy;

  // Пока в обоих списках есть узлы, пришиваем меньший
  while (list1 !== null && list2 !== null) {
    if (list1.val <= list2.val) {
      tail.next = list1;
      list1 = list1.next;
    } else {
      tail.next = list2;
      list2 = list2.next;
    }
    tail = tail.next;
  }

  // Один из списков закончился — остаток другого уже отсортирован,
  // подвешиваем его целиком
  tail.next = list1 !== null ? list1 : list2;

  return dummy.next;
}

// Время: O(n + m) — каждый узел пришивается один раз
// Память: O(1) — переиспользуем существующие узлы
